namespace TriAidPlatform.API.Alerting.Domain.Model.Aggregates;

/// <summary>
/// Aggregate root representing a medical alert generated by abnormal vital signs or a high-priority triage classification.
/// Encapsulates the state and business rules for the alert lifecycle.
/// </summary>
public class Alert
{
   /// <summary>
   /// Unique identifier for the alert
   /// </summary>
    public int Id { get; private set; }
   
   /// <summary>
   /// Identifier of the specific vital sign reading that trigger the alert
   /// </summary>
    public int ReadingId {get; private set;}
   /// <summary>
   /// Severity level of the alert
   /// </summary>
    public AlertLevel Level { get; private set; }
   /// <summary>
   /// Current lifecycle status of the alert
   /// </summary>
    public AlertStatus Status { get; private set; }
   /// <summary>
   /// The exact UTC date and time when the alert as triggered
   /// </summary>
    public DateTime RaisedAt { get; private set; }
   /// <summary>
   /// The destination to which this alert was escalated, if it's escalated 
   /// </summary>
    public string? EscalatedTo { get; private set; }
   /// <summary>
   /// The exact UTC date and time when a staff member acknowledged the alert.
   /// </summary>
    public DateTime? AcknowledgedAt { get; private set; }

   /// <summary>
   /// Protected parameterless constructor strictly required for object materialization
   /// </summary>
    protected Alert() { }

    /// <summary>
    /// Initializes a new instance of the <see cref="Alert"/> aggregate.
    /// </summary>
    /// <param name="readingId">The ID of the anomalous reading.</param>
    /// <param name="level">The severity level assigned to this alert.</param>
    public Alert(int readingId, AlertLevel level)
    {
        ReadingId = readingId;
        Level = level;
        Status = AlertStatus.Active;
        RaisedAt= DateTime.UtcNow;
    }
    
    /// <summary>
    /// Acknowledges the alert, silencing it and marking it as under review.
    /// </summary>
    /// <exception cref="InvalidOperationException">Thrown when attempting to acknowledge an alert that is already resolved.</exception>
    public void Acknowledge()
    {
        if (Status == AlertStatus.Resolved) throw new InvalidOperationException("Cannot acknowledge an already resolved alert.");
        Status = AlertStatus.Acknowledged;
        AcknowledgedAt = DateTime.UtcNow;
    }
    
    /// <summary>
    /// Escalates the alert to a critical care area.
    /// </summary>
    /// <param name="destination">The destination area (defaults to "Trauma Shock").</param>
    public void Escalate(string destination = "Trauma Shock")
    {
        Status = AlertStatus.Escalated;
        EscalatedTo = destination;
    }
    /// <summary>
    /// Marks the alert as resolved when the patient's condition stabilizes or the episode concludes (e.g., US26).
    /// </summary>
    public void Resolve()
    {
        Status = AlertStatus.Resolved;
    }
}